                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            result.setdefault(color, []).append(cells)
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    groups = components(grid)
    colors = sorted(groups)
    if len(colors) != 2 or any(len(groups[c]) != 2 for c in colors):
        return [row[:] for row in grid]

    # The same-color shapes swap vertical positions; align them in a compact
    # two-row-pair arrangement at the bottom, with rows in each shape retained.
    # The demo establishes the target stacking: one shape of each color per row.
    out = [[0] * w for _ in range(h)]
    pairs = []
    for color in colors:
        for cells in groups[color]:
            minr = min(r for r, c in cells)
            minc = min(c for r, c in cells)
            pairs.append((minr, minc, color, cells))
    # Sort components into their two original horizontal bands; colors within
    # a band are ordered left-to-right. Re-layout bands downwards.
    pairs.sort(key=lambda p: (p[0], p[1]))
    bands = []
